import type { Change, Diagnostic } from './types.js';

export type BuildStatus =
  | { ran: true; passed: boolean }
  | { ran: false; reason: 'disabled' | 'errors found' | 'no build rules' };

export type Report = {
  passed: boolean;
  summary: { errors: number; warnings: number; byRule: Record<string, number> };
  diagnostics: Diagnostic[];
  build: BuildStatus;
  /** With --fix: the edits that were applied. */
  fixed?: Change[];
};

export const toReport = (
  diagnostics: Diagnostic[],
  build: BuildStatus,
  fixed?: Change[]
): Report => {
  const byRule: Record<string, number> = {};
  for (const { rule } of diagnostics) byRule[rule] = (byRule[rule] ?? 0) + 1;
  const errors = diagnostics.filter(({ severity }) => severity === 'error').length;
  return {
    passed: errors === 0,
    summary: { errors, warnings: diagnostics.length - errors, byRule },
    diagnostics: diagnostics.map(({ rule, group, severity, file, line, column, message, fix }) => ({
      rule,
      group,
      severity,
      file,
      ...(line !== undefined && { line }),
      ...(column !== undefined && { column }),
      message,
      ...(fix && { fix }),
    })),
    build,
    ...(fixed && { fixed }),
  };
};
